<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { projectsApi, ideasApi } from '../api/services'; import { ApiError } from '../api/http'; import { useAuth } from '../composables/useAuth'; import AppLoading from '../components/AppLoading.vue'; import AppNotice from '../components/AppNotice.vue'; import type { Idea, Project, ProjectResult } from '../types/api'
const { state } = useAuth(); const projects = ref<Project[]>([]), ideas = ref<Idea[]>([]), selected = ref<Project | null>(null), results = ref<ProjectResult[]>([]), loading = ref(true), error = ref(''), success = ref(''), showCreate = ref(false), showProgress = ref(false), showResult = ref(false)
const create = ref({ ideaId: '', name: '', description: '', responsibleName: '', plannedStartDate: '', plannedEndDate: '', plannedInvestment: 0 }); const progress = ref({ stage: 'EXECUTION', status: 'IN_PROGRESS', progressPercentage: 0, actualInvestment: 0, actualEndDate: '' }); const result = ref({ type: 'COST_SAVING', nature: 'ACTUAL', description: '', periodStart: '', periodEnd: '', unit: '', baselineValue: 0, achievedValue: 0, financialAmount: 0 })
const manager = () => state.user?.role === 'MANAGER'
async function load() { loading.value = true; try { const [projectPage, ideaPage] = await Promise.all([projectsApi.list(), ideasApi.list({ status: 'APPROVED' })]); projects.value = projectPage.content; ideas.value = ideaPage.content } catch (e) { error.value = e instanceof ApiError ? e.message : 'Falha ao carregar projetos.' } finally { loading.value = false } }
async function open(item: Project) { selected.value = item; results.value = (await projectsApi.results(item.id)).content }
async function createProject() { try { await projectsApi.create(create.value); showCreate.value = false; success.value = 'Projeto criado.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível criar projeto.' } }
async function updateProgress() { if (!selected.value) return; try { await projectsApi.progress(selected.value.id, { ...progress.value, actualEndDate: progress.value.actualEndDate || null }); showProgress.value = false; await open(await projectsApi.get(selected.value.id)); success.value = 'Progresso atualizado.' } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível atualizar.' } }
async function addResult() { if (!selected.value) return; try { await projectsApi.createResult(selected.value.id, result.value); results.value = (await projectsApi.results(selected.value.id)).content; showResult.value = false; success.value = 'Resultado registrado.' } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível registrar resultado.' } }
async function archive(item: Project) { if (!confirm(`Arquivar “${item.name}”?`)) return; try { await projectsApi.archive(item.id); selected.value = null; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'Não foi possível arquivar.' } }
onMounted(load)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">EXECUÇÃO</p><h1>Projetos e resultados</h1><p>Acompanhe investimentos, etapas e benefícios realizados.</p></div><button v-if="manager()" class="button button--primary" @click="showCreate = true">Novo projeto</button></div><AppNotice tone="error" :message="error"/><AppNotice tone="success" :message="success"/><AppLoading v-if="loading"/><div v-else-if="!projects.length" class="empty"><h2>Nenhum projeto encontrado</h2><p>Projetos nascem de ideias aprovadas.</p></div><div v-else class="cards"><article v-for="item in projects" :key="item.id" class="card card--click" @click="open(item)"><div class="card-top"><span class="badge">{{ item.status }}</span><span class="badge badge--gold">{{ item.stage }}</span></div><h2>{{ item.name }}</h2><p>{{ item.responsibleName }} · {{ item.progressPercentage }}% concluído</p><div class="progress"><span :style="{ width: `${item.progressPercentage}%` }"></span></div></article></div><div v-if="showCreate" class="modal"><form class="dialog" @submit.prevent="createProject"><h2>Novo projeto</h2><label>Ideia aprovada<select v-model="create.ideaId" required><option v-for="idea in ideas" :key="idea.id" :value="idea.id">{{ idea.title }}</option></select></label><label>Nome<input v-model="create.name" required></label><label>Descrição<textarea v-model="create.description" required></textarea></label><div class="form-grid"><label>Responsável<input v-model="create.responsibleName" required></label><label>Investimento planejado<input v-model.number="create.plannedInvestment" type="number" min="0" step="0.01" required></label><label>Início<input v-model="create.plannedStartDate" type="date" required></label><label>Fim<input v-model="create.plannedEndDate" type="date" required></label></div><div class="dialog-actions"><button type="button" class="button" @click="showCreate = false">Cancelar</button><button class="button button--primary">Criar projeto</button></div></form></div><div v-if="selected" class="modal"><section class="dialog dialog--wide"><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p><p><strong>Investimento:</strong> R$ {{ selected.actualInvestment }} realizado de R$ {{ selected.plannedInvestment }} planejado.</p><div class="progress"><span :style="{ width: `${selected.progressPercentage}%` }"></span></div><div v-if="manager()" class="dialog-actions"><button class="button" @click="showProgress = true">Atualizar progresso</button><button class="button" @click="showResult = true">Registrar resultado</button><button class="button button--danger" @click="archive(selected)">Arquivar</button></div><h3>Resultados</h3><div v-if="!results.length" class="empty compact"><p>Nenhum resultado registrado.</p></div><ul v-else class="result-list"><li v-for="entry in results" :key="entry.id"><strong>{{ entry.type }} · {{ entry.nature }}</strong><span>{{ entry.description }}</span><span>R$ {{ entry.financialAmount }}</span></li></ul><div class="dialog-actions"><button class="button" @click="selected = null">Fechar</button></div></section></div><div v-if="showProgress && selected" class="modal"><form class="dialog" @submit.prevent="updateProgress"><h2>Atualizar progresso</h2><div class="form-grid"><label>Etapa<select v-model="progress.stage"><option>PLANNING</option><option>EXECUTION</option><option>CLOSURE</option></select></label><label>Status<select v-model="progress.status"><option>PLANNED</option><option>IN_PROGRESS</option><option>COMPLETED</option><option>CANCELLED</option></select></label><label>Progresso<input v-model.number="progress.progressPercentage" type="number" min="0" max="100"></label><label>Investimento realizado<input v-model.number="progress.actualInvestment" type="number" min="0" step="0.01"></label><label>Conclusão real<input v-model="progress.actualEndDate" type="date"></label></div><div class="dialog-actions"><button type="button" class="button" @click="showProgress = false">Cancelar</button><button class="button button--primary">Atualizar</button></div></form></div><div v-if="showResult && selected" class="modal"><form class="dialog" @submit.prevent="addResult"><h2>Registrar resultado</h2><div class="form-grid"><label>Tipo<select v-model="result.type"><option>COST_SAVING</option><option>ADDITIONAL_REVENUE</option><option>PRODUCTIVITY</option><option>TIME_REDUCTION</option></select></label><label>Natureza<select v-model="result.nature"><option>FORECAST</option><option>ACTUAL</option></select></label><label>Período inicial<input v-model="result.periodStart" type="date" required></label><label>Período final<input v-model="result.periodEnd" type="date" required></label><label>Valor financeiro<input v-model.number="result.financialAmount" type="number" min="0" step="0.01"></label></div><label>Descrição<textarea v-model="result.description" required></textarea></label><div class="dialog-actions"><button type="button" class="button" @click="showResult = false">Cancelar</button><button class="button button--primary">Registrar</button></div></form></div></section></template>
